/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen1Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private fields of CategoryPlot via reflection
     * because the fields are not exposed via public setters in the provided signature.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(Map<Integer, ArrayList<Marker>> foreground, Map<Integer, ArrayList<Marker>> background) throws Exception {
        Field fgField = CategoryPlot.class.getDeclaredField("foregroundDomainMarkers");
        fgField.setAccessible(true);
        fgField.set(plot, foreground);

        Field bgField = CategoryPlot.class.getDeclaredField("backgroundDomainMarkers");
        bgField.setAccessible(true);
        bgField.set(plot, background);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_MarkersNull_ReturnsTrue() throws Exception {
        Map<Integer, ArrayList<Marker>> fg = new HashMap<>();
        Map<Integer, ArrayList<Marker>> bg = new HashMap<>();
        injectMarkers(fg, bg);

        // Index 0 is not in the map, so get(0) returns null
        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.FOREGROUND, true);
        assertTrue("Should return true if markers list is null", result);
    }

    @Test
    public void testRemoveDomainMarker_Background_MarkersNull_ReturnsTrue() throws Exception {
        Map<Integer, ArrayList<Marker>> fg = new HashMap<>();
        Map<Integer, ArrayList<Marker>> bg = new HashMap<>();
        injectMarkers(fg, bg);

        // Index 0 is not in the map, so get(0) returns null
        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.BACKGROUND, true);
        assertTrue("Should return true if markers list is null", result);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_MarkerFound_RemovedReturnsTrue() throws Exception {
        Map<Integer, ArrayList<Marker>> fg = new HashMap<>();
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        fg.put(0, markers);

        Map<Integer, ArrayList<Marker>> bg = new HashMap<>();
        injectMarkers(fg, bg);

        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.FOREGROUND, true);
        assertTrue("Should return true when marker is successfully removed", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_MarkerNotFound_ReturnsFalse() throws Exception {
        Map<Integer, ArrayList<Marker>> fg = new HashMap<>();
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mock(Marker.class)); // different marker
        fg.put(0, markers);

        Map<Integer, ArrayList<Marker>> bg = new HashMap<>();
        injectMarkers(fg, bg);

        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.FOREGROUND, true);
        assertFalse("Should return false when marker is not in the list", result);
        assertEquals(1, markers.size());
    }

    @Test
    public void testRemoveDomainMarker_Background_MarkerFound_RemovedReturnsTrue() throws Exception {
        Map<Integer, ArrayList<Marker>> fg = new HashMap<>();
        Map<Integer, ArrayList<Marker>> bg = new HashMap<>();
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        bg.put(0, markers);
        injectMarkers(fg, bg);

        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.BACKGROUND, true);
        assertTrue("Should return true when marker is successfully removed from background", result);
        assertTrue(markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_NotifyFalse_DoesNotTriggerLogic() throws Exception {
        // Note: We cannot easily verify fireChangeEvent() without a spy or checking side effects,
        // but we can ensure the return value is correct when notify is false.
        Map<Integer, ArrayList<Marker>> fg = new HashMap<>();
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        fg.put(0, markers);

        Map<Integer, ArrayList<Marker>> bg = new HashMap<>();
        injectMarkers(fg, bg);

        // Testing path where removed is true but notify is false
        boolean result = plot.removeDomainMarker(0, mockMarker, Layer.FOREGROUND, false);
        assertTrue("Should return true even if notify is false", result);
        assertTrue(markers.isEmpty());
    }
}
